import sys
import heapq

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    m = int(next(it, 0))
    n = int(next(it, 0))

    if m == 0 or n == 0:
        print(0)
        return

    grid = []
    for _ in range(m):
        row = []
        for _ in range(n):
            row.append(int(next(it, 0)))
        grid.append(row)

    INF = 10**18
    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = grid[0][0]

    pq = [(grid[0][0], 0, 0)]
    dirs = [(0, 1), (1, 0)]  # right, down

    while pq:
        cost, r, c = heapq.heappop(pq)
        if cost != dist[r][c]:
            continue
        if r == m - 1 and c == n - 1:
            print(cost)
            return
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                new_cost = cost + grid[nr][nc]
                if new_cost < dist[nr][nc]:
                    dist[nr][nc] = new_cost
                    heapq.heappush(pq, (new_cost, nr, nc))

    print(dist[m-1][n-1])

if __name__ == "__main__":
    solve()
